arguments.command:
cd /workspace && python3 - <<'PYEOF'
p='src/fib.hpp'
s=open(p).read()
s=s.replace("""    bool has_len(int len) const {
        if (len < 64) return (len_mask_lo_ >> len) & 1ULL;
        return (len_mask_hi_ >> (len - 64)) & 1ULL;
    }
    std::unordered_map<FibKey, uint32_t, FibKeyHash> entries_;
    uint64_t len_mask_lo_ = 0;  // lengths 0..63
    uint64_t len_mask_hi_ = 0;  // lengths 64..128""","""    bool has_len(int len) const {
        if (len < 0 || len > 128) return false;
        return len_mask_[len] != 0;
    }
    std::unordered_map<FibKey, uint32_t, FibKeyHash> entries_;
    std::array<char, 129> len_mask_{};""")
s=s.replace("""#include <cstdint>
#include <unordered_map>
#include <vector>""","""#include <array>
#include <cstdint>
#include <unordered_map>
#include <vector>""")
open(p,'w').write(s)

p='src/fib.cpp'
s=open(p).read()
s=s.replace("""    entries_[key] = hop;
    if (len < 64) len_mask_lo_ |= (1ULL << len);
    else len_mask_hi_ |= (1ULL << (len - 64));""","""    entries_[key] = hop;
    len_mask_[len] = 1;""")
s=s.replace("""    entries_.clear();
    len_mask_lo_ = 0;
    len_mask_hi_ = 0;""","""    entries_.clear();
    len_mask_.fill(0);""")
open(p,'w').write(s)
PYEOF
python3 build.py 2>&1 | tail -3 && python3 /tmp/runex.py
